DROP INDEX IF EXISTS "gate_entries_one_open_truck_key"; DROP INDEX IF EXISTS "gate_entries_one_open_crew_pass_key"; CREATE UNIQUE INDEX "gate_entries_one_open_truck_key" ON "gate_entries" ("businessDate", UPPER("actualTankTruckNumber")) WHERE "status" = 'IN' AND "isDeleted" = FALSE; CREATE UNIQUE INDEX "gate_entries_one_open_crew_pass_key" ON "gate_entries" ("businessDate", "crewPassId") WHERE "status" = 'IN' AND "isDeleted" = FALSE;
